local function createSlider(parent, order, title, minVal, maxVal, defaultVal, onChanged)
    local f=Instance.new("Frame",parent) f.LayoutOrder=order f.Size=UDim2.new(1,-4,0,68) f.BackgroundColor3=Color3.fromRGB(24,22,36) f.BackgroundTransparency=0.15 Instance.new("UICorner",f).CornerRadius=UDim.new(0,12) Instance.new("UIStroke",f).Color=Color3.fromRGB(60,55,80) Instance.new("UIStroke",f).Transparency=0.6
    local dot=Instance.new("Frame",f) dot.Size=UDim2.fromOffset(6,6) dot.Position=UDim2.new(0,12,0,14) dot.BackgroundColor3=ACCENT Instance.new("UICorner",dot).CornerRadius=UDim.new(1,0)
    local t=Instance.new("TextLabel",f) t.Text=title t.Position=UDim2.new(0,26,0,8) t.Size=UDim2.new(0.5,0,0,12) t.BackgroundTransparency=1 t.Font=Enum.Font.GothamBold t.TextSize=12 t.TextColor3=Color3.new(1,1,1) t.TextXAlignment=Enum.TextXAlignment.Left
    local vLabel=Instance.new("TextLabel",f) vLabel.Text=tostring(defaultVal).." SPD" vLabel.Position=UDim2.new(0.5,0,0,8) vLabel.Size=UDim2.new(0.5,-12,0,12) vLabel.BackgroundTransparency=1 vLabel.Font=Enum.Font.GothamBold vLabel.TextSize=11 vLabel.TextColor3=ACCENT vLabel.TextXAlignment=Enum.TextXAlignment.Right
    local trackF=Instance.new("Frame",f) trackF.Name="Track" trackF.Size=UDim2.new(1,-24,0,6) trackF.Position=UDim2.new(0,12,0,36) trackF.BackgroundColor3=Color3.fromRGB(34,30,50) trackF.BorderSizePixel=0 Instance.new("UICorner",trackF).CornerRadius=UDim.new(1,0)
    local fill=Instance.new("Frame",trackF) fill.Name="Fill" fill.Size=UDim2.new(0,0,1,0) fill.BackgroundColor3=ACCENT fill.BorderSizePixel=0 Instance.new("UICorner",fill).CornerRadius=UDim.new(1,0) Instance.new("UIGradient",fill).Color=ColorSequence.new{ColorSequenceKeypoint.new(0,ACCENT),ColorSequenceKeypoint.new(1,ACCENT2)}
    local knob=Instance.new("Frame",trackF) knob.Name="Knob" knob.Size=UDim2.fromOffset(18,18) knob.AnchorPoint=Vector2.new(0.5,0.5) knob.Position=UDim2.new(0,0,0.5,0) knob.BackgroundColor3=Color3.new(1,1,1) knob.BorderSizePixel=0 Instance.new("UICorner",knob).CornerRadius=UDim.new(1,0) Instance.new("UIStroke",knob).Color=ACCENT
    local hitbox=Instance.new("TextButton",trackF) hitbox.Size=UDim2.new(1,0,1,12) hitbox.Position=UDim2.new(0,0,0,-6) hitbox.BackgroundTransparency=1 hitbox.Text="" hitbox.ZIndex=5
    local dragging=false
    local curVal=defaultVal
    local function pctFromVal(v) return math.clamp((v-minVal)/(maxVal-minVal),0,1) end
    local function valFromPct(p) return math.clamp(minVal + p*(maxVal-minVal), minVal, maxVal) end
    local function updateVisual(v, instant)
        curVal=v
        local pct=pctFromVal(v)
        vLabel.Text=string.format("%d SPD [Real: %.1f]", v, getRealHumanoidSpeed())
        if instant then
            fill.Size=UDim2.new(pct,0,1,0)
            knob.Position=UDim2.new(pct,0,0.5,0)
        else
            tw(fill,{Size=UDim2.new(pct,0,1,0)},0.15):Play()
            tw(knob,{Position=UDim2.new(pct,0,0.5,0)},0.15):Play()
        end
    end
    local function setFromMouse(x)
        local absPos=trackF.AbsolutePosition.X
        local absSize=trackF.AbsoluteSize.X
        if absSize==0 then return end
        local pct=math.clamp((x-absPos)/absSize,0,1)
        local v=valFromPct(pct)
        v=math.floor(v+0.5)
        sliderSpeed=v
        updateVisual(v,false)
        if onChanged then onChanged(v) end
    end
    track(hitbox, function(startPos) dragging=true setFromMouse(startPos.X) return nil end,
        function(dx,dy,state,moved,pos) if dragging then setFromMouse(pos.X) end end,
        function() dragging=false end)
    track(knob, function(startPos) dragging=true return nil end,
        function(dx,dy,state,moved,pos) if dragging then setFromMouse(pos.X) end end,
        function() dragging=false end)
    updateVisual(defaultVal,true)
    task.spawn(function()
        while f.Parent do
            if not dragging then
                local real=getRealHumanoidSpeed()
                vLabel.Text=string.format("%d SPD [Real: %.1f]", curVal, real)
            end
            task.wait(0.3)
        end
    end)
    return {
        frame=f,
        setValue=function(v) curVal=v sliderSpeed=v updateVisual(v,true) if onChanged then onChanged(v) end end,
        getValue=function() return curVal end
    }
end

local function createDropdownLib(tabAPI, scroll, desiredOrder, title, options, multi, default, callback)
    local cfg={
        Title=title,
        Desc=" ",
        Flag=title:gsub(" ","").."_LIB_"..tostring(desiredOrder)..tostring(math.random(100,999)),
        Options=options,
        Default=default,
        Multi=multi,
        Callback=callback
    }
    local api = tabAPI:Dropdown(cfg)
    return api
end

